import path from 'node:path';

import type { FieldDefinition } from '@/contracts/types';
import type { CountryCode } from '@/types/domain';
import type { FieldLabel, ResolvedField } from './resolve';

import { isVisible } from '@/contracts/visibility';
import { STEPS } from '@/lib/constants/steps';
import { COUNTRY_CODES } from '@/types/domain';

import { REPO_ROOT } from './files';
import { formatSource } from './format';

const HEADER =
  '// Generated by contracts/inventory/generate.ts — do not edit.\n';

const words = (value: string): string[] => value.split(/[-_]/);
const pascal = (value: string): string =>
  words(value)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join('');
const camel = (value: string): string => {
  const name = pascal(value);
  return name.charAt(0).toLowerCase() + name.slice(1);
};

const tsType = (field: ResolvedField): string => {
  switch (field.type) {
    case 'integer':
    case 'decimal':
      return 'number';
    case 'boolean':
      return 'boolean';
    case 'multi_catalog':
      return 'string[]';
    case 'phone':
      return 'PhoneValue';
    case 'string':
    case 'date':
    case 'email':
    case 'url':
    case 'catalog':
      return 'string';
    default:
      return field.type satisfies never;
  }
};

/** Non-optional only when every country always shows and requires it. */
const isAlwaysPresent = (field: ResolvedField): boolean => {
  const { required } = field;
  return (
    field.collection === undefined &&
    field.countries.length === COUNTRY_CODES.length &&
    field.visible_when === undefined &&
    (required === 'when_visible' ||
      field.countries.every((country) => required[country] ?? true))
  );
};

const definitionOf = (field: ResolvedField): FieldDefinition => {
  const {
    key,
    block,
    type,
    countries,
    required,
    catalog,
    visible_when,
    validation,
    max_length,
    multiline,
    help,
    preload_from,
    read_only,
    ui_only,
    collection,
    parent_collection,
    item_tab,
    item_group,
    item_title,
    person_field,
    identity,
    full_width,
    min_items,
    max_items,
    min_items_when_any,
    sole_item_not,
    variant,
  } = field;
  return {
    key,
    block,
    type,
    countries,
    required,
    ...(catalog && { catalog }),
    ...(visible_when && { visible_when }),
    ...(validation && { validation }),
    ...(max_length !== undefined && { max_length }),
    ...(multiline && { multiline }),
    ...(help && { help }),
    ...(preload_from && { preload_from }),
    ...(read_only && { read_only }),
    ...(ui_only && { ui_only }),
    ...(collection && { collection }),
    ...(parent_collection && { parent_collection }),
    ...(item_tab !== undefined && { item_tab }),
    ...(item_group !== undefined && { item_group }),
    ...(item_title && { item_title }),
    ...(person_field !== undefined && { person_field }),
    ...(identity && { identity }),
    ...(full_width && { full_width }),
    ...(min_items !== undefined && { min_items }),
    ...(max_items !== undefined && { max_items }),
    ...(min_items_when_any && { min_items_when_any }),
    ...(sole_item_not && { sole_item_not }),
    ...(variant && { variant }),
  };
};

const dtoLines = (fields: ResolvedField[], optional: boolean): string =>
  fields
    .map(
      (field) =>
        `  ${field.key}${optional || !isAlwaysPresent(field) ? '?' : ''}: ${tsType(field)};`,
    )
    .join('\n');

/** Section order follows the sheet. */
const groupBySection = (
  fields: ResolvedField[],
): Map<string, ResolvedField[]> => {
  const sections = new Map<string, ResolvedField[]>();
  for (const field of fields) {
    sections.set(field.section, [
      ...(sections.get(field.section) ?? []),
      field,
    ]);
  }
  return sections;
};

const dataFields = (fields: ResolvedField[]): ResolvedField[] =>
  fields.filter((field) => field.ui_only !== true);

/** Collections held directly by `owner` (the section when undefined), in sheet order. */
const collectionsOf = (
  fields: ResolvedField[],
  owner?: string,
): Map<string, ResolvedField[]> => {
  const collections = new Map<string, ResolvedField[]>();
  for (const field of fields) {
    if (field.collection !== undefined && field.parent_collection === owner) {
      collections.set(field.collection, [
        ...(collections.get(field.collection) ?? []),
        field,
      ]);
    }
  }
  return collections;
};

const collectionLines = (collections: Map<string, ResolvedField[]>): string[] =>
  [...collections.keys()].map(
    (name) => `  ${name}?: ${pascal(name)}ItemDto[];`,
  );

const sectionDto = (section: string, fields: ResolvedField[]): string => {
  const data = dataFields(fields);
  const top = collectionsOf(data);
  const items = [...top].flatMap(([name, members]) => {
    const children = collectionsOf(data, name);
    return [
      ...[...children].map(
        ([child, own]) =>
          `interface ${pascal(child)}ItemDto {\n${dtoLines(own, true)}\n}`,
      ),
      `interface ${pascal(name)}ItemDto {\n${[dtoLines(members, true), ...collectionLines(children)].filter(Boolean).join('\n')}\n}`,
    ];
  });
  const own = dtoLines(
    data.filter((field) => field.collection === undefined),
    false,
  );

  return [
    ...items,
    `interface ${pascal(section)}Dto {\n${[own, ...collectionLines(top)].filter(Boolean).join('\n')}\n}`,
  ].join('\n\n');
};

/**
 * Blocks of the step named like the overlay, in `STEPS` order, with the number
 * of fields each shows per country before anything is answered. Each
 * collection counts as one field; blocks with no field are omitted.
 */
const blocksByCountry = (
  name: string,
  fields: ResolvedField[],
): Record<CountryCode, { key: string; fields: number }[]> => {
  const order = STEPS.find((step) => step.slug === name)?.blocks ?? [];

  return Object.fromEntries(
    COUNTRY_CODES.map((country) => [
      country,
      order
        .map((key) => {
          const shown = fields.filter(
            (field) =>
              field.block === key &&
              field.ui_only !== true &&
              field.countries.includes(country) &&
              isVisible(field.visible_when, {}, country),
          );
          const collections = new Set(
            shown.flatMap(
              (field) => field.parent_collection ?? field.collection ?? [],
            ),
          );
          return {
            key,
            fields:
              shown.filter((field) => field.collection === undefined).length +
              collections.size,
          };
        })
        .filter((block) => block.fields > 0),
    ]),
  ) as Record<CountryCode, { key: string; fields: number }[]>;
};

const emitContract = (name: string, fields: ResolvedField[]): string => {
  const id = camel(name);
  const sections = groupBySection(fields);
  const blocks: string[] = [];

  for (const [section, members] of sections) {
    const sectionId = camel(section);
    blocks.push(
      sectionDto(section, members),
      `const ${sectionId}Fields = ${JSON.stringify(members.map(definitionOf), null, 2)} as const satisfies readonly FieldDefinition[];`,
      `const ${sectionId}SchemaFor = (country: CountryCode, context: Record<string, unknown> = {}) =>\n  buildSectionSchema(${sectionId}Fields, country, context);`,
    );
  }

  const keys = [...sections.keys()];
  const hasPhone = dataFields(fields).some((field) => field.type === 'phone');
  const sectionExports = keys.flatMap((section) => [
    `${camel(section)}Fields`,
    `${camel(section)}SchemaFor`,
    `type ${pascal(section)}Dto`,
  ]);
  const itemTypes = fields
    .filter((field) => field.collection !== undefined && field.ui_only !== true)
    .map((field) => `type ${pascal(field.collection ?? '')}ItemDto`);
  const exports = [
    `${id}BlocksByCountry`,
    `${id}Contract`,
    `${id}Fields`,
    `${id}SchemaFor`,
    `${id}SectionKeys`,
    ...sectionExports,
    ...new Set(itemTypes),
  ];

  return `${HEADER}
import type { BlockFieldCount${keys.length > 0 ? ', FieldDefinition' : ''}${hasPhone ? ', PhoneValue' : ''} } from '@/contracts/types';
import type { CountryCode } from '@/types/domain';

${keys.length > 0 ? "import { buildSectionSchema } from '@/contracts/section-schema';\n\n" : ''}${blocks.map((block) => `${block}\n\n`).join('')}const ${id}SectionKeys = ${JSON.stringify(keys)} as const;

const ${id}BlocksByCountry = ${JSON.stringify(blocksByCountry(name, fields), null, 2)} as const satisfies Record<CountryCode, readonly BlockFieldCount[]>;

const ${id}Fields = {
${keys.map((section) => `  '${section}': ${camel(section)}Fields,`).join('\n')}
} as const;

const ${id}SchemaFor = {
${keys.map((section) => `  '${section}': ${camel(section)}SchemaFor,`).join('\n')}
} as const;

/** What the step-agnostic form and the rail read of this step. */
const ${id}Contract = {
  sectionKeys: ${id}SectionKeys,
  fields: ${id}Fields,
  schemaFor: ${id}SchemaFor,
  blocksByCountry: ${id}BlocksByCountry,
} as const;

export {
  ${exports.join(',\n  ')},
};
`;
};

const sampleNumber = (field: ResolvedField): number => {
  let value = field.type === 'integer' ? 1 : 1.5;
  for (const rule of field.validation ?? []) {
    if ('min' in rule) value = Math.max(value, rule.min);
    if ('max' in rule) value = Math.min(value, rule.max);
  }
  return value;
};

const sampleValue = (field: ResolvedField): unknown => {
  switch (field.type) {
    case 'string':
      // Dashes, not underscores: identification numbers only take letters, digits, dots and dashes.
      return `sample-${field.key.replaceAll('_', '-')}`.slice(
        0,
        field.max_length,
      );
    case 'integer':
    case 'decimal':
      return sampleNumber(field);
    case 'date':
      return '2021-01-15';
    case 'boolean':
      return true;
    case 'email':
      return 'sample@example.com';
    case 'url':
      return 'https://example.com';
    case 'phone':
      return { dial_code: '+505', number: '88887777' };
    case 'catalog':
      return `cat-${field.catalog?.name ?? 'unknown'}-1`;
    case 'multi_catalog':
      return [`cat-${field.catalog?.name ?? 'unknown'}-1`];
    default:
      return field.type satisfies never;
  }
};

/** Sample of one level (the section, or an item of `owner`); a collection gets `min_items` items (at least one). */
const sampleFor = (
  fields: ResolvedField[],
  country: CountryCode,
  owner?: string,
): Record<string, unknown> => {
  const sample: Record<string, unknown> = {};
  const applicable = dataFields(fields).filter((field) =>
    field.countries.includes(country),
  );
  for (const field of applicable) {
    if (field.collection === owner) sample[field.key] = sampleValue(field);
  }
  for (const [name, members] of collectionsOf(applicable, owner)) {
    const item = sampleFor(fields, country, name);
    sample[name] = Array.from(
      { length: Math.max(members[0]?.min_items ?? 1, 1) },
      () => item,
    );
  }
  return sample;
};

const emitFixtures = (name: string, fields: ResolvedField[]): string => {
  const sections = groupBySection(fields);
  const blocks: string[] = [];
  for (const [section, members] of sections) {
    const byCountry = Object.fromEntries(
      COUNTRY_CODES.map((country) => [country, sampleFor(members, country)]),
    );
    blocks.push(
      `const ${camel(section)}Fixtures: Record<CountryCode, ${pascal(section)}Dto> = ${JSON.stringify(byCountry, null, 2)};`,
    );
  }
  const keys = [...sections.keys()];
  const imports =
    keys.length === 0 ?
      ''
    : `import type {
  ${keys.map((section) => `${pascal(section)}Dto`).join(',\n  ')},
} from '@/contracts/generated/${name}';
import type { CountryCode } from '@/types/domain';

${blocks.join('\n\n')}

`;

  return `${HEADER}
${imports}const ${camel(name)}Fixtures = {
${keys.map((section) => `  '${section}': ${camel(section)}Fixtures,`).join('\n')}
} as const;

export { ${camel(name)}Fixtures };
`;
};

const LOCALES = ['es', 'en'] as const;

const allLabels = (fields: ResolvedField[]): FieldLabel[] =>
  fields.flatMap((field) => field.labels);

/** Labels with no English copy: the English file falls back to Spanish. */
const untranslatedLabels = (fields: ResolvedField[]): string[] =>
  allLabels(fields)
    .filter((label) => label.en === undefined)
    .map((label) => label.id);

/** `{ <Name>Fields: { labels: { <id>: text } } }` for one locale. */
const emitLabels = (
  name: string,
  fields: ResolvedField[],
  locale: (typeof LOCALES)[number],
): string => {
  const labels = Object.fromEntries(
    allLabels(fields).map((label) => [
      label.id,
      locale === 'en' ? (label.en ?? label.es) : label.es,
    ]),
  );
  const hints = Object.fromEntries(
    fields.flatMap((field) =>
      field.help_text === undefined ?
        []
      : [[field.key, field.help_text[locale]]],
    ),
  );
  return JSON.stringify(
    {
      [`${pascal(name)}Fields`]: {
        labels,
        ...(Object.keys(hints).length > 0 && { hints }),
      },
    },
    null,
    2,
  );
};

/** Output path (repo-relative) to formatted content for one overlay. */
const emitOverlay = async (
  name: string,
  fields: ResolvedField[],
): Promise<Map<string, string>> => {
  const files = new Map<string, string>([
    [`src/contracts/generated/${name}.ts`, emitContract(name, fields)],
    [`test/fixtures/generated/${name}.ts`, emitFixtures(name, fields)],
    ...LOCALES.map((locale): [string, string] => [
      `i18n/${locale}/${name}-fields.json`,
      emitLabels(name, fields, locale),
    ]),
  ]);
  for (const [file, source] of files) {
    files.set(file, await formatSource(source, path.join(REPO_ROOT, file)));
  }
  return files;
};

export { emitOverlay, untranslatedLabels };
